1	import { Injectable, NotFoundException } from '@nestjs/common';
2	import { SupabaseService } from '../supabase/supabase.service';
3	
4	@Injectable()
5	export class EmpresasService {
6	  constructor(private supabase: SupabaseService) {}
7	
8	  private gerarSlug(name: string): string {
9	    return name.toLowerCase().replace(/[^a-z0-9\s-]/g, '').replace(/\s+/g, '-').trim();
10	  }
11	
12	  async listar(apenasAtivo?: boolean) {
13	    let query = this.supabase.client
14	      .from('restaurants')
15	      .select('id, name, address, logo_url, comissao_pct, user_id, slug, bloqueado, custom_domain, custom_domain_status, custom_domain_solicitado_em, custom_domain_motivo_recusa, modulo_delivery, modulo_salao, created_at')
16	      .order('name');
17	
18	    const { data, error } = await query;
19	    if (error) throw error;
20	    return { empresas: data, total: data?.length ?? 0 };
21	  }
22	
23	  async buscar(id: number) {
24	    const { data, error } = await this.supabase.client
25	      .from('restaurants')
26	      .select('id, name, address, logo_url, business_hours, payment_config, comissao_pct, user_id, slug, modulo_delivery, modulo_salao, created_at')
27	      .eq('id', id)
28	      .maybeSingle();
29	
30	    if (error) throw error;
31	    if (!data) throw new NotFoundException(`Empresa ${id} não encontrada`);
32	
33	    const [{ data: metricas }, { data: platData }] = await Promise.all([
34	      this.supabase.client.from('orders').select('id, total, status').eq('restaurant_id', id),
35	      this.supabase.client.from('platform_settings').select('config').eq('id', 1).maybeSingle(),
36	    ]);
37	
38	    const entregues = (metricas ?? []).filter((p) => p.status === 'delivered');
39	    const faturamento = entregues.reduce((acc, p) => acc + (p.total ?? 0), 0);
40	    const platCfg = (platData?.config ?? {}) as Record<string, any>;
41	    const comissaoPct = data.comissao_pct ?? platCfg.comissao_padrao_pct ?? 5;
42	
43	    return {
44	      empresa: data,
45	      metricas: {
46	        total_pedidos: metricas?.length ?? 0,
47	        pedidos_entregues: entregues.length,
48	        faturamento,
49	        comissao_acumulada: parseFloat((faturamento * (comissaoPct / 100)).toFixed(2)),
50	      },
51	    };
52	  }
53	
54	  async criar(body: {
55	    name: string;
56	    address?: string;
57	    logo_url?: string;
58	    comissao_pct?: number;
59	    user_id?: string;
60	    slug?: string;
61	    modulo_delivery?: boolean;
62	    modulo_salao?: boolean;
63	  }) {
64	    const { data, error } = await this.supabase.client
65	      .from('restaurants')
66	      .insert({
67	        name: body.name,
68	        address: body.address ?? null,
69	        logo_url: body.logo_url ?? null,
70	        comissao_pct: body.comissao_pct ?? null,
71	        user_id: body.user_id || null,
72	        slug: body.slug || this.gerarSlug(body.name),
73	        modulo_delivery: body.modulo_delivery ?? true,
74	        modulo_salao: body.modulo_salao ?? false,
75	      })
76	      .select()
77	      .single();
78	
79	    if (error) throw error;
80	    return data;
81	  }
82	
83	  async atualizar(id: number, body: Partial<{
84	    name: string;
85	    address: string;
86	    logo_url: string;
87	    comissao_pct: number;
88	    business_hours: object;
89	    payment_config: object;
90	    user_id: string;
91	    modulo_delivery: boolean;
92	    modulo_salao: boolean;
93	  }>) {
94	    const payload: Record<string, any> = { ...body, updated_at: new Date().toISOString() };
95	    if ('user_id' in payload && !payload.user_id) payload.user_id = null;
96	
97	    const { data, error } = await this.supabase.client
98	      .from('restaurants')
99	      .update(payload)
100	      .eq('id', id)
101	      .select()
102	      .single();
103	
104	    if (error) throw error;
105	    if (!data) throw new NotFoundException(`Empresa ${id} não encontrada`);
106	    return data;
107	  }
108	
109	  async bloquear(id: number, bloqueado: boolean) {
110	    const { data, error } = await this.supabase.client
111	      .from('restaurants')
112	      .update({ bloqueado, updated_at: new Date().toISOString() })
113	      .eq('id', id)
114	      .select('id, name, bloqueado')
115	      .single();
116	    if (error) throw error;
117	    return data;
118	  }
119	
120	  async atenderSolicitacaoDominio(id: number) {
121	    const { data, error } = await this.supabase.client
122	      .from('restaurants')
123	      .update({
124	        custom_domain_status: null,
125	        custom_domain_motivo_recusa: null,
126	        updated_at: new Date().toISOString(),
127	      })
128	      .eq('id', id)
129	      .select('id, name, custom_domain, custom_domain_status')
130	      .maybeSingle();
131	
132	    if (error) throw error;
133	    if (!data) throw new NotFoundException(`Empresa ${id} não encontrada`);
134	    return data;
135	  }
136	
137	  async recusarSolicitacaoDominio(id: number, motivo: string) {
138	    const { data, error } = await this.supabase.client
139	      .from('restaurants')
140	      .update({
141	        custom_domain_status: 'recusado',
142	        custom_domain_motivo_recusa: motivo || 'Não especificado',
143	        updated_at: new Date().toISOString(),
144	      })
145	      .eq('id', id)
146	      .select('id, name, custom_domain, custom_domain_status, custom_domain_motivo_recusa')
147	      .maybeSingle();
