1	import React, { createContext, useContext, useEffect, useState } from 'react';
2	import { supabase } from '../lib/supabase';
3	import { getMeuPlanoStatus } from '../services/restauranteService';
4	
5	const AuthContext = createContext({})
6	
7	export const useAuth = () => {
8	  const context = useContext(AuthContext)
9	  if (!context) {
10	    throw new Error('useAuth must be used within AuthProvider')
11	  }
12	  return context
13	}
14	
15	export const AuthProvider = ({ children }) => {
16	  const [user, setUser] = useState(null)
17	  const [userProfile, setUserProfile] = useState(null)
18	  const [loading, setLoading] = useState(true)
19	  const [authError, setAuthError] = useState(null)
20	  const [planoStatus, setPlanoStatus] = useState(null)
21	
22	  useEffect(() => {
23	    // Get initial session - Use Promise chain
24	    supabase?.auth?.getSession()?.then(({ data: { session } }) => {
25	        if (session?.user) {
26	          setUser(session?.user)
27	          fetchUserProfile(session?.user?.id)
28	        }
29	        setLoading(false)
30	      })?.catch((error) => {
31	        setAuthError('Failed to get session. Please check your Supabase connection.')
32	        setLoading(false)
33	      })
34	
35	    // Listen for auth changes - NEVER ASYNC callback
36	    const { data: { subscription } } = supabase?.auth?.onAuthStateChange(
37	      (event, session) => {
38	        if (session?.user) {
39	          setUser(session?.user)
40	          fetchUserProfile(session?.user?.id)
41	        } else {
42	          setUser(null)
43	          setUserProfile(null)
44	        }
45	        setLoading(false)
46	        setAuthError(null)
47	      }
48	    )
49	
50	    return () => subscription?.unsubscribe()
51	  }, [])
52	
53	  // Status da assinatura do plano — só relevante pro dono, carregado 1x por
54	  // sessão (RestauranteGuard usa isso pra bloquear o painel se estiver vencido).
55	  const refreshPlanoStatus = () => {
56	    if (userProfile?.role !== 'restaurant_owner') return;
57	    getMeuPlanoStatus().then(setPlanoStatus).catch(() => {});
58	  };
59	
60	  useEffect(() => {
61	    if (userProfile?.role === 'restaurant_owner') {
62	      getMeuPlanoStatus().then(setPlanoStatus).catch(() => {});
63	    } else {
64	      setPlanoStatus(null);
65	    }
66	  }, [userProfile?.role])
67	
68	  const fetchUserProfile = (userId) => {
69	    supabase?.from('user_profiles')?.select('*')?.eq('id', userId)?.single()?.then(({ data, error }) => {
70	        if (error) {
71	          setAuthError(`Failed to fetch user profile: ${error?.message}`)
72	          return
73	        }
74	        setUserProfile(data)
75	      })
76	  }
77	
78	  const signIn = async (email, password) => {
79	    setAuthError(null)
80	    setLoading(true)
81	    
82	    try {
83	      const { data, error } = await supabase?.auth?.signInWithPassword({
84	        email,
85	        password
86	      })
87	      
88	      if (error) {
89	        setAuthError(error?.message)
90	        return { success: false, error: error?.message };
91	      }
92	      
93	      return { success: true, user: data?.user };
94	    } catch (error) {
95	      if (error?.message?.includes('Failed to fetch') || 
96	          error?.message?.includes('AuthRetryableFetchError')) {
97	        setAuthError('Cannot connect to authentication service. Your Supabase project may be paused or inactive. Please check your Supabase dashboard and resume your project if needed.')
98	        return { success: false, error: 'Connection failed' }
99	      }
100	      
101	      setAuthError('Something went wrong. Please try again.')
102	      return { success: false, error: 'Authentication failed' }
103	    } finally {
104	      setLoading(false)
105	    }
106	  }
107	
108	  const signUp = async (email, password, userData = {}) => {
109	    setAuthError(null)
110	    setLoading(true)
111	    
112	    try {
113	      const { data, error } = await supabase?.auth?.signUp({
114	        email,
115	        password,
116	        options: {
117	          data: {
118	            name: userData?.name || email?.split('@')?.[0],
119	            role: userData?.role || 'customer',
