1	import { supabase } from '../lib/supabase';
2	import { apiPath } from '../lib/apiUrl';
3	
4	const API = apiPath('/api');
5	
6	async function apiFetch(path, options = {}) {
7	  const sessionResult = await supabase.auth.getSession().catch(() => ({ data: {} }));
8	  const token = sessionResult?.data?.session?.access_token;
9	
10	  if (!token) throw new Error('Sessão expirada. Faça login novamente.');
11	
12	  const res = await fetch(`${API}${path}`, {
13	    ...options,
14	    headers: {
15	      'Content-Type': 'application/json',
16	      'Authorization': `Bearer ${token}`,
17	      ...options.headers,
18	    },
19	  });
20	
21	  const contentType = res.headers.get('content-type') ?? '';
22	  const isJson = contentType.includes('application/json');
23	
24	  if (!res.ok) {
25	    if (isJson) {
26	      const err = await res.json().catch(() => ({}));
27	      throw new Error(err?.message ?? `HTTP ${res.status}`);
28	    }
29	    throw new Error(`HTTP ${res.status} — backend indisponível`);
30	  }
31	
32	  if (!isJson) {
33	    throw new Error('Resposta inválida do servidor. Verifique se o backend está rodando na porta 3002.');
34	  }
35	
36	  return res.json();
37	}
38	
39	// Plataforma
40	export const getPlataformaConfig = () => apiFetch('/plataforma/config');
41	export const updatePlataformaConfig = (data) =>
42	  apiFetch('/plataforma/config', { method: 'PATCH', body: JSON.stringify(data) });
43	export const getRedeInfo = () => apiFetch('/plataforma/rede');
44	export const getMetricas = () => apiFetch('/plataforma/metricas');
45	export const getComissoes = (params = {}) => {
46	  const qs = new URLSearchParams(Object.entries(params).filter(([, v]) => v)).toString();
47	  return apiFetch(`/plataforma/comissoes${qs ? `?${qs}` : ''}`);
48	};
49	export const getComissoesPorEmpresa = (id) => apiFetch(`/plataforma/comissoes/empresa/${id}`);
50	
51	// Empresas
52	export const getEmpresas = () => apiFetch('/empresas');
53	export const getEmpresa = (id) => apiFetch(`/empresas/${id}`);
54	export const criarEmpresa = (data) => apiFetch('/empresas', { method: 'POST', body: JSON.stringify(data) });
55	export const atualizarEmpresa = (id, data) => apiFetch(`/empresas/${id}`, { method: 'PATCH', body: JSON.stringify(data) });
56	export const bloquearEmpresa = (id, bloqueado) => apiFetch(`/empresas/${id}/bloquear`, { method: 'PATCH', body: JSON.stringify({ bloqueado }) });
57	export const removerEmpresa = (id) => apiFetch(`/empresas/${id}`, { method: 'DELETE' });
58	export const atenderSolicitacaoDominio = (id) => apiFetch(`/empresas/${id}/dominio/atender`, { method: 'PATCH' });
59	export const recusarSolicitacaoDominio = (id, motivo) =>
60	  apiFetch(`/empresas/${id}/dominio/recusar`, { method: 'PATCH', body: JSON.stringify({ motivo }) });
61	
62	// Config pagamentos por empresa
63	export const getEmpresaConfig = (id) => apiFetch(`/empresas/${id}/config`);
64	export const updateEmpresaConfig = (id, data) =>
65	  apiFetch(`/empresas/${id}/config`, { method: 'PATCH', body: JSON.stringify(data) });
66	
67	// Pedidos
68	export const getPedidos = (params = {}) => {
69	  const qs = new URLSearchParams(Object.entries(params).filter(([, v]) => v)).toString();
70	  return apiFetch(`/pedidos${qs ? `?${qs}` : ''}`);
71	};
72	export const atualizarStatusPedido = (id, status) =>
73	  apiFetch(`/pedidos/${id}/status`, { method: 'PATCH', body: JSON.stringify({ status }) });
74	
75	// Produtos
76	export const getProdutos = (empresaId, apenasAtivos = false) =>
77	  apiFetch(`/empresas/${empresaId}/produtos${apenasAtivos ? '?apenas_ativos=true' : ''}`);
78	export const toggleProduto = (id, ativo) =>
79	  apiFetch(`/produtos/${id}/toggle`, { method: 'PATCH', body: JSON.stringify({ ativo }) });
80	
81	// Categorias por empresa
82	export const getCategorias = (empresaId) => apiFetch(`/empresas/${empresaId}/categorias`);
83	
84	// Tags do catálogo — admin CRUD
85	export const getTags = () => apiFetch('/admin/tags');
