import { BadRequestException, Injectable, NotFoundException } from '@nestjs/common';
import { SupabaseService } from '../supabase/supabase.service';
import { GeocodingService } from '../motoboy/geocoding.service';

const SELECT_PERFIL = 'id, name, email, phone_e164, address_json, foto_perfil_url';

@Injectable()
export class PerfilService {
  constructor(
    private supabase: SupabaseService,
    private geocoding: GeocodingService,
  ) {}

  async getMeuPerfil(userId: string) {
    const { data } = await this.supabase.client
      .from('customers')
      .select(SELECT_PERFIL)
      .eq('user_id', userId)
      .maybeSingle();

    if (data) return data;

    // Primeira vez: cria a partir dos dados do user_profiles
    const { data: up } = await this.supabase.client
      .from('user_profiles')
      .select('name, email')
      .eq('id', userId)
      .maybeSingle();

    const { data: novo } = await this.supabase.client
      .from('customers')
      .insert({ name: up?.name ?? 'Cliente', email: up?.email ?? null, user_id: userId })
      .select(SELECT_PERFIL)
      .single();

    return novo;
  }

  async updateMeuPerfil(
    userId: string,
    body: { name?: string; phone_e164?: string; address_json?: Record<string, any> },
  ) {
    if (body.address_json) {
      const { logradouro, numero } = body.address_json;
      if (!logradouro?.toString().trim() || !numero?.toString().trim()) {
        throw new BadRequestException('Endereço precisa de logradouro e número');
      }
    }

    const { data: existing } = await this.supabase.client
      .from('customers')
      .select('id, address_geocode_hash')
      .eq('user_id', userId)
      .maybeSingle();

    let data: any;
    let customerId: number;

    if (existing) {
      const res = await this.supabase.client
        .from('customers')
        .update({ ...body, updated_at: new Date().toISOString() })
        .eq('id', existing.id)
        .select(SELECT_PERFIL)
        .single();
      data = res.data;
      customerId = existing.id;
    } else {
      const { data: up } = await this.supabase.client
        .from('user_profiles')
        .select('email')
        .eq('id', userId)
        .maybeSingle();

      const res = await this.supabase.client
        .from('customers')
        .insert({ ...body, email: up?.email ?? null, user_id: userId })
        .select(SELECT_PERFIL)
        .single();
      data = res.data;
      customerId = data.id;
    }

    // Geocodifica o endereço salvo pra alimentar o filtro por raio/KM da home quando o
    // cliente não tiver GPS ao vivo — nunca deixa uma falha do Nominatim derrubar o save.
    if (body.address_json) {
      try {
        const resultado = await this.geocoding.geocodificarSeNecessario(body.address_json, existing?.address_geocode_hash ?? null);
        if (resultado) {
          await this.supabase.client
            .from('customers')
            .update({
              lat: resultado.lat,
              lng: resultado.lng,
              address_geocode_hash: resultado.hash,
              address_geocoded_at: new Date().toISOString(),
            })
            .eq('id', customerId);
        }
      } catch {
        // silencioso — perfil já foi salvo, geocodificação é best-effort
      }
    }

    return data;
  }

  // Bucket público separado do de imagens de produto/restaurante — foto de perfil não é
  // documento sensível (diferente das fotos/documentos de motoboy, que usam URL assinada).
  private async setupStorageAvatares() {
    const BUCKET = 'customer-avatars';
    const { data: buckets } = await this.supabase.client.storage.listBuckets();
    const exists = (buckets ?? []).some((b: any) => b.id === BUCKET);

    if (!exists) {
      const { error } = await this.supabase.client.storage.createBucket(BUCKET, {
        public: true,
        fileSizeLimit: 5 * 1024 * 1024,
        allowedMimeTypes: ['image/jpeg', 'image/jpg', 'image/png', 'image/webp', 'image/gif'],
      });
      if (error) throw error;
    }
  }

  async uploadFoto(userId: string, file: Express.Multer.File) {
    const { data: customer } = await this.supabase.client
      .from('customers')
      .select('id')
      .eq('user_id', userId)
      .maybeSingle();
    if (!customer) throw new NotFoundException('Perfil não encontrado');

    const BUCKET = 'customer-avatars';
    await this.setupStorageAvatares();

    const ext = (file.originalname.split('.').pop() ?? 'jpg').toLowerCase();
    const path = `${customer.id}/${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${ext}`;

    const { error } = await this.supabase.client.storage
      .from(BUCKET)
      .upload(path, file.buffer, { cacheControl: '3600', upsert: false, contentType: file.mimetype });
    if (error) throw error;

    const { data: pub } = this.supabase.client.storage.from(BUCKET).getPublicUrl(path);

    await this.supabase.client
      .from('customers')
      .update({ foto_perfil_url: pub.publicUrl, updated_at: new Date().toISOString() })
      .eq('id', customer.id);

    return { foto_perfil_url: pub.publicUrl };
  }
}

const BASE_LINKS = [
  { label: 'Dashboard', path: '/restaurante', icon: 'LayoutDashboard' },
  { label: 'Relatórios', path: '/restaurante/relatorios', icon: 'BarChart3' },
  { label: 'Produtos', path: '/restaurante/produtos', icon: 'Package' },
  { label: 'Clientes', path: '/restaurante/clientes', icon: 'UserRound' },
  { label: 'Financeiro', path: '/restaurante/financeiro', icon: 'Wallet' },
  { label: 'Caixa', path: '/restaurante/caixa', icon: 'PiggyBank' },
  { label: 'Designer', path: '/restaurante/aparencia', icon: 'Paintbrush' },
  { label: 'Cardápio Digital', path: '/restaurante/cardapio-digital', icon: 'BookOpen' },
  { label: 'Config', path: '/restaurante/config', icon: 'Settings' },
  { label: 'Plano', path: '/restaurante/plano', icon: 'CreditCard' },
  { label: 'Sessão', path: '/restaurante/sessao', icon: 'Clock' },
];

// Servem tanto Delivery quanto Salão — só somem se a empresa não tem NENHUM módulo ativo.
const COMPARTILHADO_LINKS = [
  { label: 'Cozinha', path: '/restaurante/cozinha', icon: 'ChefHat' },
  { label: 'Combos', path: '/restaurante/combos', icon: 'Boxes' },
  { label: 'Pedidos', path: '/restaurante/pedidos', icon: 'ClipboardList' },
];

const DELIVERY_LINKS = [
  { label: 'Delivery', path: '/restaurante/delivery', icon: 'Truck' },
  { label: 'Entregas', path: '/restaurante/entregas', icon: 'Bike' },
  { label: 'Motoboys', path: '/restaurante/motoboys', icon: 'Users' },
];

const COPA_LINKS = [
  { label: 'Produção', path: '/restaurante/producao', icon: 'CookingPot' },
  { label: 'Bar', path: '/restaurante/bar', icon: 'Beer' },
];

const SALAO_LINKS = [
  { label: 'Salão', path: '/restaurante/salao', icon: 'UtensilsCrossed' },
  { label: 'Chamada', path: '/restaurante/chamada', icon: 'Volume2' },
  { label: 'Garçons', path: '/restaurante/garcons', icon: 'Contact' },
  { label: 'Impressoras', path: '/restaurante/impressoras', icon: 'Printer' },
];

export const getRestauranteNavLinks = (moduloDelivery, moduloSalao) => {
  const temAlgumModulo = moduloDelivery || moduloSalao;
  const links = [
    ...BASE_LINKS.slice(0, 2), // Dashboard, Relatórios
    ...(moduloDelivery ? DELIVERY_LINKS.slice(0, 1) : []), // Delivery
    ...(temAlgumModulo ? COMPARTILHADO_LINKS.slice(0, 1) : []), // Cozinha
    ...(moduloSalao ? COPA_LINKS : []), // Produção, Bar
    ...BASE_LINKS.slice(2, 3), // Produtos
    ...(temAlgumModulo ? COMPARTILHADO_LINKS.slice(1) : []), // Combos, Pedidos
    ...(moduloDelivery ? DELIVERY_LINKS.slice(1) : []), // Entregas, Motoboys
    ...BASE_LINKS.slice(3), // Clientes...Sessão
    ...(moduloSalao ? SALAO_LINKS : []), // Salão, Garçons, Impressoras
  ];
  // Menu lateral em ordem alfabética (pedido do usuário) — a ordem acima só
  // controla quais links entram conforme os módulos ativos. Dashboard fica
  // fixo no topo, fora da ordenação.
  const [dashboard, resto] = [links.find((l) => l.path === '/restaurante'), links.filter((l) => l.path !== '/restaurante')];
  resto.sort((a, b) => a.label.localeCompare(b.label, 'pt-BR'));
  return dashboard ? [dashboard, ...resto] : resto;
};

